import json,re,subprocess
from pathlib import Path
out=Path(__file__).resolve().parent
base=subprocess.check_output(['git','rev-parse','origin/main'],text=True).strip()
results=[json.loads(s) for s in (out/'results.jsonl').read_text().splitlines()]
mutants=json.loads((out/'mutants-results.json.txt').read_text());audit=[]
for r in mutants:
 text=(out/'mutants'/r['name']/'test.txt').read_text()
 failures=re.findall(r'--- FAIL: (Test\S+) \(([\d.]+)s\)',text)
 invalid=re.findall(r'(?im)^.*(?:\.[ch]:\d+(?::\d+)?: (?:fatal )?error:|\[build failed\]|panic: test timed out|no space left on device|signal: killed).*$',text)
 assert r['caught'] and failures and not invalid,(r['name'],invalid)
 assert all(float(t)<60 for _,t in failures)
 audit.append(dict(name=r['name'],failures=failures,command=r['command']))
assert len(audit)==14
(out/'mutant-catcher-audit.json.txt').write_text(json.dumps(audit,indent=2)+'\n')
counts=json.loads((out/'counts-changes.json.txt').read_text());scan=json.loads((out/'after.json.txt').read_text())
text=['Re-cut slice 3 onto current main, preserving both sides of reuse.go.', 'Branch: compiler/loom-r-slice-3-ac-m3; base: '+base+'; source: bb1cc531484bc1a10da05041b23bac330a69c6c9.', 'Native/lower recursive tests, counts regeneration, guards, vet, gofmt and a-check pass.', 'All 14 production mutants and both header mutants are caught by their intended checks.', 'Not covered: full repository gate, Loom submission and formatter reruns; two existing cold count-product leaves exceeded 60 seconds.', '', '## Resolution and assumptions','', 'The fetched origin/main tip is fixed for this verification and delivery. Applied only bb1cc531\'s own change using the requested merge-tree base and cherry-pick --no-commit. The single conflict is checkDefined in internal/native/reuse.go: keep slice 3\'s catchable TypeError branch and main\'s cArray(message) initializer in the invariant-panic fallback. Main\'s automatically merged closure constructors remain, with source_length initialization added. No other main line was reverted by resolution.', '', 'Counts were reset to main and regenerated once on Linux with house clang 20.1.8. Exactly 33 rows differ from main: 22 additions and 11 existing rows. All resulting moved-row values match bb1cc531. Every carried .a file remains byte-identical to bb1cc531. No header or pinned-position changes.', '', '## Runtime lines','', 'No additional runtime C/H lines beyond the source commit. The complete own delta remains exactly:', '', '```', 'internal/native/runtime/adamic.h: + size_t source_length;', 'internal/native/runtime/closure.c: + closure->source_length = 0;', 'internal/native/runtime/union.c:', '+ if (value != NULL && value->kind == adamic_kind_closure && strcmp(name, "length") == 0) {', '+     return adamic_box_number((double)((adamic_closure *)value)->source_length);', '+ }', '```', '', 'source-runtime.patch and recut-runtime.patch have identical added/deleted lines; runtime-audit.txt records the comparison.', '', '## Commands and results','', 'Every Go test used -count=1 and a hard timeout, with direct log output. Four-CPU affinity and GOMAXPROCS=4 were used. Products preceded their ordinary consumers. Exact commands and timing events are in results.jsonl and the corresponding logs/seconds files.', '', '| Check | Exit | Wall seconds | Notes |','|---|---:|---:|---|']
for r in results:
 note='; '.join(x['test']+' '+str(x['seconds'])+'s' for x in r['over_budget'])
 if r['exit']:note+=' Environment storage failure, repaired below.'
 text.append('| '+r['name']+' | '+str(r['exit'])+' | '+str(r['seconds'])+' | '+note+' |')
text += ['', 'Formatting: gofmt.txt is empty; production git diff --check passes. Native/lower products and consumer leaves all stayed under 60 seconds. Two unmodified count-product leaves passed at 63.89 and 65.24 seconds (CountMeasurements00 and 15); neither was rerun or altered. No test was added, split or deleted in this re-cut. The user explicitly accepted existing formatter cold-product timings; those packages were not rerun.', '', 'The first reader run and the first serial flow product attempt failed only with no space left on device. Regenerable Go-export snapshots were evicted and byte-identical completed archives deduplicated. All four reader products and the reader/SortedMap guard then passed. The bounded second dedup attempt reached its 45-second limit after partial safe progress; a later inode-aware pass completed and reclaimed 3,034,699,730 duplicate bytes. No source workaround was made for storage.', '', 'Setup completed in 70.869s: node 0.036s; go 0.040s; submodules 0.110s; markdown 0.119s; clang 0.226s; WASI SDK 0.430s; shared cache 1.617s; go build 70.554s; test binaries deferred 70.753s; cache warm 70.755s. nproc=5; cgroup quota is four CPUs. Sourced /workspace/adamic-tools/env.sh. Go 1.27.1, Node 24.19.0, clang 20.1.8.', '', 'Native validation retained the prior task-local GCC wrapper: system GCC 14 lacks sanitizer/allocator_interface.h despite libasan exporting the required functions. The wrapper adds only the house LLVM allocator header and declares its digest in --version (94be5aa9568359b0a1e331836221d05713d6810c28c6ed688d2aea6f3861348d). WASI_SYSROOT points to the installed house SDK. Runtime sources and tests were not edited for either environment condition.', '', '## Production mutants and catchers','', '| Mutant | Behavioral catcher |','|---|---|']
for r in audit:text.append('| '+r['name']+' | '+'; '.join(n+' ('+t+'s)' for n,t in r['failures'])+' |')
text += ['', 'All overlays affect actual production paths, are retained as .go.txt files, and failed by test assertions, without compile errors, timeout, OOM or storage errors. Header mutants removed the first-line refusal header or replaced its reason on function_call.a; both retained compiler status refused and failed the pinned a-check predicate with exit 1.', '', '## A-check status','', 'Counts: '+json.dumps(scan['counts'])+'. NotYet: 0. Type error: 0. Predicate exit: '+str(scan['exit'])+'.', '', '| File | Status |','|---|---|']
for p,r in scan['rows'].items():text.append('| '+p+' | '+r['status']+' |')
text += ['', '## Every moved counts row','', '| Fixture | Before | After |','|---|---|']
for r in counts:
 def values(line):return ', '.join(x.strip() for x in line.split('|')[2:-1]) if line else 'new row'
 text.append('| '+r['fixture']+' | '+values(r['before'])+' | '+values(r['after'])+' |')
text += ['', 'Column order: allocations, frees, retains, releases, peak live, in regions. No unrelated rows changed. No ahra command, full gate, PR or Loom submission was run. No formatter work was pursued. Earlier inherited source reports and commit-body notes describe earlier cuts; this report describes this re-cut.']
(out/'REPORT.md').write_text('\n'.join(text)+'\n')
